    const restored = restoredRecords(imported, original.profile)
    for (const key of ['transactions', 'accounts', 'goals', 'budgets', 'dailyBudgets', 'contributions', 'plannedSpending', 'transfers', 'balanceAdjustments', 'profile'] as const) expect(restored[key]).toEqual(original[key])
